import csv
import io
import json
import re
import unicodedata
from datetime import datetime, timedelta, timezone
from pathlib import Path

from clubroll import dates, ids
from clubroll.errors import DataError
from clubroll.members import tag_list

RULES = ("email", "name-dob", "phone-name")
KEEP_APART_HEADER = ["first", "second", "note"]
CHANGE_ORDER = ("name", "email", "phone", "dob", "expires", "marketing", "tags", "updated")
FROM_FIELDS = ("name", "email", "phone", "dob", "expires")


# ---------------------------------------------------------------- settings

class Settings:
    def __init__(self, country: str, trunk: str, dotless: set[str], aliases: dict[str, str]):
        self.country = country
        self.trunk = trunk
        self.dotless = dotless
        self.aliases = aliases


def load_settings(path: Path) -> Settings:
    try:
        doc = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise DataError("settings", f"cannot read {path}: {e}") from None
    try:
        phone, email = doc["phone"], doc["email"]
        country, trunk = phone["country"], phone["trunk"]
        dotless, domain_aliases = email["dotless_domains"], email["domain_aliases"]
        if not isinstance(country, str) or not isinstance(trunk, str):
            raise TypeError("phone settings")
        if not isinstance(dotless, list) or not all(isinstance(d, str) for d in dotless):
            raise TypeError("dotless_domains")
        if not isinstance(domain_aliases, dict) or not all(
                isinstance(k, str) and isinstance(v, str) for k, v in domain_aliases.items()):
            raise TypeError("domain_aliases")
    except (KeyError, TypeError):
        raise DataError("settings", f"{path}: unexpected structure") from None
    return Settings(country, trunk, set(dotless), dict(domain_aliases))


def load_keep_apart(path: Path) -> list[tuple[int, int]]:
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return []
    except OSError as e:
        raise DataError("keep-apart", f"cannot read {path}: {e}") from None
    rows = list(csv.reader(io.StringIO(text, newline="")))
    if not rows or rows[0] != KEEP_APART_HEADER:
        raise DataError("keep-apart", f"{path}: header is not {','.join(KEEP_APART_HEADER)}")
    out = []
    for n, row in enumerate(rows[1:], start=2):
        if len(row) != 3:
            raise DataError("keep-apart", f"{path}:{n}: expected 3 fields")
        a, b = ids.number(row[0]), ids.number(row[1])
        if a is None or b is None:
            raise DataError("keep-apart", f"{path}:{n}: not a member id")
        out.append((a, b))
    return out


# -------------------------------------------------------------------- keys

def name_key(text: str) -> str:
    t = unicodedata.normalize("NFKD", text)
    t = "".join(c for c in t if not unicodedata.combining(c)).casefold()
    t = "".join(c if (unicodedata.category(c)[0] == "L" or unicodedata.category(c) == "Nd") else " " for c in t)
    return " ".join(t.split())


def email_key(text: str, s: Settings) -> str:
    t = text.strip().lower()
    if t.count("@") != 1:
        return ""
    local, domain = t.split("@")
    domain = s.aliases.get(domain, domain)
    local = local.split("+", 1)[0]
    if domain in s.dotless:
        local = local.replace(".", "")
    if not local or not domain:
        return ""
    return f"{local}@{domain}"


def phone_key(text: str, s: Settings) -> str:
    t = text.replace("(0)", "")
    t = "".join(c for c in t if c in "0123456789+")
    if "+" in t[1:]:
        return ""
    if t.startswith("+"):
        key = t[1:]
    elif t.startswith("00"):
        key = t[2:]
    elif t.startswith(s.trunk):
        key = s.country + t[len(s.trunk):]
    else:
        return ""
    if not 9 <= len(key) <= 15:
        return ""
    return key


_TIME_Z = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2}):([0-9]{2})Z\Z")
_TIME_OFF = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2}):([0-9]{2})([+-])([0-9]{2}):([0-9]{2})\Z")
_TIME_DAY = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})\Z")


def parse_updated(text: str) -> datetime:
    """The instant of an `updated` value (data.md, section 2); ValueError for any other form."""
    m = _TIME_Z.match(text)
    if m:
        y, mo, d, h, mi, sec = map(int, m.groups())
        return datetime(y, mo, d, h, mi, sec, tzinfo=timezone.utc)
    m = _TIME_OFF.match(text)
    if m:
        y, mo, d, h, mi, sec = map(int, m.groups()[:6])
        sign = -1 if m.group(7) == "-" else 1
        delta = timedelta(hours=int(m.group(8)), minutes=int(m.group(9))) * sign
        if int(m.group(8)) > 23 or int(m.group(9)) > 59:
            raise ValueError(f"bad offset: {text!r}")
        return datetime(y, mo, d, h, mi, sec, tzinfo=timezone(delta))
    m = _TIME_DAY.match(text)
    if m:
        y, mo, d = map(int, m.groups())
        return datetime(y, mo, d, tzinfo=timezone.utc)
    raise ValueError(f"not a time: {text!r}")


# ------------------------------------------------------------------ groups

class Group:
    def __init__(self, n: int, dob):
        self.members = [n]
        self.dobs = {dob} if dob is not None else set()
        self.rules: set[str] = set()


def plan(members: dict[int, dict], aliases: dict[int, int], settings: Settings,
         apart_rows: list[tuple[int, int]]):
    """Returns (groups, refused): groups are (survivor, Group); refused are (low, high, rule)."""
    info = {}
    for n, r in members.items():
        nk = name_key(r["name"])
        info[n] = {
            "name": nk,
            "given": nk.split(" ")[0] if nk else "",
            "email": email_key(r["email"], settings),
            "phone": phone_key(r["phone"], settings),
            "dob": dates.parse_day(r["dob"]),
        }

    apart: dict[int, set[int]] = {}
    for x, y in apart_rows:
        x, y = aliases.get(x, x), aliases.get(y, y)
        if x == y or x not in members or y not in members:
            continue
        apart.setdefault(x, set()).add(y)
        apart.setdefault(y, set()).add(x)

    def rule_of(a: int, b: int):
        ia, ib = info[a], info[b]
        if ia["email"] and ia["email"] == ib["email"] and ia["given"] and ia["given"] == ib["given"]:
            return "email"
        if ia["name"] and ia["name"] == ib["name"] and ia["dob"] is not None and ia["dob"] == ib["dob"]:
            return "name-dob"
        if ia["name"] and ia["name"] == ib["name"] and ia["phone"] and ia["phone"] == ib["phone"]:
            return "phone-name"
        return None

    # candidate pairs, found through buckets to avoid comparing everyone with everyone
    buckets: dict[tuple, list[int]] = {}
    for n in sorted(members):
        i = info[n]
        if i["email"] and i["given"]:
            buckets.setdefault(("e", i["email"], i["given"]), []).append(n)
        if i["name"]:
            if i["dob"] is not None:
                buckets.setdefault(("d", i["name"], i["dob"]), []).append(n)
            if i["phone"]:
                buckets.setdefault(("p", i["name"], i["phone"]), []).append(n)
    candidates = set()
    for lst in buckets.values():
        for x in range(len(lst)):
            for y in range(x + 1, len(lst)):
                candidates.add((lst[x], lst[y]))
    pairs = []
    for a, b in candidates:
        rule = rule_of(a, b)
        if rule is not None:
            pairs.append((RULES.index(rule), a, b))
    pairs.sort()

    group_of = {n: Group(n, info[n]["dob"]) for n in members}
    refused = []
    for ri, a, b in pairs:
        ga, gb = group_of[a], group_of[b]
        if ga is gb:
            continue
        gbset = set(gb.members)
        kept = any(d1 != d2 for d1 in ga.dobs for d2 in gb.dobs)
        if not kept:
            kept = any(apart.get(x, set()) & gbset for x in ga.members)
        if kept:
            refused.append((a, b, RULES[ri]))
            continue
        ga.members.extend(gb.members)
        ga.dobs |= gb.dobs
        ga.rules |= gb.rules
        ga.rules.add(RULES[ri])
        for x in gb.members:
            group_of[x] = ga

    groups = []
    seen = set()
    for g in group_of.values():
        if id(g) in seen or len(g.members) < 2:
            continue
        seen.add(id(g))
        survivor = min(g.members, key=lambda n: (dates.parse_day(members[n]["joined"]), n))
        groups.append((survivor, g))
    groups.sort(key=lambda t: t[0])
    return groups, refused


def merged_record(members: dict[int, dict], survivor: int, g: Group, stamp: str):
    """(new record, changes, sources) for a group."""
    old = members[survivor]
    order = sorted(g.members, key=lambda n: (-parse_updated(members[n]["updated"]).timestamp(), n))
    # instants compared exactly (timestamp() floats are exact for whole seconds in this range)
    new = dict(old)
    sources: dict[str, int] = {}

    def first_nonempty(field):
        for n in order:
            if members[n][field] != "":
                return n
        return None

    if old["name"] == "":
        n = first_nonempty("name")
        if n is not None:
            new["name"] = members[n]["name"]
            sources["name"] = n
    for f in ("email", "phone", "dob"):
        n = first_nonempty(f)
        new[f] = members[n][f] if n is not None else ""
        if n is not None:
            sources[f] = n
    days = {n: dates.parse_day(members[n]["expires"]) for n in g.members if members[n]["expires"] != ""}
    if days:
        latest = max(days.values())
        n = next(n for n in order if n in days and days[n] == latest)
        new["expires"] = members[n]["expires"]
        sources["expires"] = n
    else:
        new["expires"] = ""
    vals = [members[n]["marketing"] for n in g.members]
    new["marketing"] = "no" if "no" in vals else ("yes" if "yes" in vals else "")
    new["tags"] = sorted({t for n in g.members for t in tag_list(members[n])})
    new["updated"] = stamp

    changes = {}
    for f in CHANGE_ORDER:
        if new[f] != old[f]:
            changes[f] = [old[f], new[f]]
    src = {f: ids.fmt(sources[f]) for f in FROM_FIELDS if f in changes and f in sources}
    return new, changes, src


def dump(value) -> str:
    return json.dumps(value, ensure_ascii=False)
